use crate::ir::{Instruction, IrModule, Operand};
pub fn optimize(mut module: IrModule) -> IrModule { for function in &mut module.functions { function.instructions = function.instructions.iter().map(|instruction| match instruction { Instruction::Binary { destination, operator, left: Operand::Constant(left), right: Operand::Constant(right) } => { let value = match operator.as_str() { "add" => left + right, "sub" => left - right, "mul" => left * right, "div" if *right != 0 => left / right, _ => return instruction.clone() }; Instruction::Constant { destination: destination.clone(), value } }, _ => instruction.clone() }).collect(); } module }
